  -- data/triggers/055/055_22_degeneration_status_checker.lua
  (55, 22, $trig$-- Converted from DG Script #5522: degeneration_status_checker
-- Reminds the actor of their Degeneration quest stage when they say
-- "spell" or "progress". The cat tells the player to use these keywords,
-- so the script must always run on match. Legacy DG header listed
-- probability 0% but the original always ran on keyword match -- the
-- converter's percent_chance(0) gate has been removed.

-- Speech phrase: spell progress (DG num_arg 0 = the speech contains the whole phrase, on word boundaries)
local speech_padded = " " .. string.lower(speech) .. " "
if not string.find(speech_padded, "[%s%p]spell progress[%s%p]") then
    return true  -- Not the phrase
end
wait(0.2)
local stage = actor:get_quest_stage("degeneration")
self:say("You are trying to help me finish the spell Degeneration.")
-- (empty room echo)
if stage == 1 then
    self:say("Find Yajiro in Odaishyozen and bring back his book.")
elseif stage == 2 then
    self.room:send(tostring(self.name) .. " says, 'Find Mesmeriz in the Minithawkin Mines and bring back his")
    self.room:send("</>necklace.'")
elseif stage == 3 then
    self:say("Find Luchiaans in Nordus and bring back his mask.")
elseif stage == 4 then
    self:say("Find Voliangloch in Demise Keep and bring back his rod.")
elseif stage == 5 then
    self:say("Find Kryzanthor in the Graveyard and bring back his robe.")
elseif stage == 6 then
    self.room:send(tostring(self.name) .. " says, 'Find Ureal the Lich in the Barrow and bring back his")
    self.room:send("</>statuette.'")
elseif stage == 7 or stage == 8 then
    self.room:send(tostring(self.name) .. " says, 'Find Norisent in the Cathedral of Betrayal and bring back")
    self.room:send("</>his book.'")
elseif stage == 9 then
    self:say("Find the enormous ruby hidden under a stairway.")
end$trig$, '3242588e7609827c7c62c1aee1723a80'),
  -- data/triggers/060/060_06_quest_timulos_training.lua
  (60, 6, $trig$-- Converted from DG Script #6006: quest_timulos_training
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"training"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end
wait(0.2)
if string.find(actor.class, "rogue") then
    if actor.level >= 10 and actor.level <= 25 then
        if not use_subclass then
            self:command("nod " .. tostring(actor.name))
            actor:send(tostring(self.name) .. " says, 'Well which would you like to train as: <yellow>mercenary</>, <red>assassin</>, or <b:red>thief</>?'")
            wait(1)
            actor:send(tostring(self.name) .. " says, 'Say one of them.'")
        else
            actor:send(tostring(self.name) .. " says, 'One moment, I'm getting someone else set up.'")
            actor:send(tostring(self.name) .. " ushers you into the corner.")
            self.room:send_except(actor, tostring(self.name) .. " ushers " .. tostring(actor.name) .. " into the corner.")
            wait(2)
            actor:send(tostring(self.name) .. " says, 'Wait there.'")
        end
    elseif actor.level < 10 then
        actor:send(tostring(self.name) .. " says, 'I like your zeal, but it's a little too soon for you to subclass, kid.'")
    else
        actor:send(tostring(self.name) .. " says, 'It's waaaaaaay too late to train you.  That ship has sailed!'")
    end
else
    actor:send(tostring(self.name) .. " says, 'Go find someone else to train with.'")
    wait(0.2)
    -- this may need to be changed in the future if new classes are invented that aren't just <name>s for pluralizing.
    actor:send(tostring(self.name) .. " says, 'I don't work with " .. tostring(actor.class) .. "s.'")
end$trig$, 'b1a577ca25bcc974be19ec3698d2432d'),
