    wait(0.2)
    actor:send(tostring(self.name) .. " says, 'Bring back proof of the deed and you shall be accepted.'")
else
    local classgreet = "no"
    if actor.alignment < -349 then
        local in_window =
            (string.find(actor.class, "warrior") and actor.level <= 25)
