if not speech_hit then
    return true  -- None of the listed words
end
self:say("Very well, goodbye little one.")
actor:send("A gust of wind, commanded by Eleweiss, catches you and moves you away.")
self.room:send_except(actor, "A gust of wind from Eleweiss moves " .. tostring(actor.name) .. " away.")
actor:teleport(get_room(163, 74))$trig$, '446791e5d5daea91727f96ac92d00135'),
  -- data/triggers/163/163_09_quest_eleweiss_ranger_druid_subclass_status.lua
  (163, 9, $trig$-- Speech phrase: subclass progress (DG num_arg 0 = the speech contains the whole phrase, on word boundaries)
local speech_padded = " " .. string.lower(speech) .. " "
if not string.find(speech_padded, "[%s%p]subclass progress[%s%p]") then
    return true  -- Not the phrase
end

wait(0.2)
local stage = actor:get_quest_stage("ran_dru_subclass")
if stage == 1 then
    actor:send(tostring(self.name) .. " says, 'Only the most dedicated to the forests shall complete the <b:cyan>quest</> I set upon you.'")
elseif stage == 2 then
    actor:send(tostring(self.name) .. " says, 'Yes, quest. I do suppose it would help if I told you about it.'")
    self:emote("rubs his chin thoughtfully.")
    wait(1)
    actor:send(tostring(self.name) .. " says, 'Long ago I <b:cyan>lost something</>.  It is a shame, but it has never been recovered.'")
    self:command("sigh")
    actor:send(tostring(self.name) .. " says, 'If you were to help me with that, then we could arrange something.'")
    self:emote("looks hopeful.")
elseif stage == 3 or stage == 4 then
    self:command("sigh")
    actor:send(tostring(self.name) .. " says, 'It seems I am becoming forgetful in my age.'")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'Well, you see now, I lost the jewel of my heart. If you are up to it, finding and returning it to me will get you your reward.'")
    self:command("shrug")
    wait(0.2)
    actor:send(tostring(self.name) .. " says, 'But for now, it is time for you to depart I think.'")
    self:command("sigh")
    actor:send(tostring(self.name) .. " says, 'You have brought up painful memories for me to relive.'")
else
    -- TODO(parity): legacy DG had a race switch ("ADD NEW RESTRICTED RACES HERE")
    -- that halted on disallowed races before the level checks below.
    if string.find(actor.class, "cleric") then
        if actor.level >= 10 and actor.level <= 35 then
            actor:send(tostring(self.name) .. " says, 'You are not on this quest.'")
        elseif actor.level < 10 then
            actor:send(tostring(self.name) .. " says, 'Seek me again later when you have gained some more experience.'")
        else
            actor:send(tostring(self.name) .. " says, 'You have traveled too far on your current path to change your way.'")
        end
    elseif string.find(actor.class, "warrior") then
        if actor.level >= 10 and actor.level <= 25 then
            actor:send(tostring(self.name) .. " says, 'You are not on this quest.'")
        elseif actor.level < 10 then
            actor:send(tostring(self.name) .. " says, 'Seek me again later when you have gained some more experience.'")
        else
            actor:send(tostring(self.name) .. " says, 'You have traveled too far on your current path to change your way.'")
        end
    end
end$trig$, 'ce883839da9a382923028935e75ee529'),
  -- data/triggers/163/163_41_dryad_moonwell_again.lua
  (163, 41, $trig$-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"druid?", "druid", "promising?", "promising", "again?", "again"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

if actor.class ~= "druid" or actor.level < 73 then
    return true
end

globals.moon_name = actor.name

wait(0.5)
self:command("sigh")
wait(1)
actor:send(tostring(self.name) .. " tells you, 'Yes, well...'")
self.room:send_except(actor, tostring(self.name) .. " tells something to " .. tostring(actor.name) .. ".")
wait(0.5)
self.room:send(tostring(self.name) .. " starts to reminisce about her past.")
wait(0.5)
actor:send(tostring(self.name) .. " tells you, 'You see, I was not always like this.  Many years ago I\n"
    .. "</>too was a young mortal druid.  But while on my journeys I made a grave error in\n"
    .. "</>judgement.'")
wait(3)
actor:send(tostring(self.name) .. " tells you, 'I rediscovered powerful magics that allowed me to travel\n"
    .. "</>the world on a whim.'")
wait(3)
actor:send(tostring(self.name) .. " tells you, 'But I squandered that magic on frivolous desires and\n"
    .. "</>furthering my own ambitions, rather than using it to better perform my sworn\n"
    .. "</>duties.'")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Thus the great goddess Mielikki punished me by binding me\n"
    .. "</>to this tree as a dryad so I might never travel again.'")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Now, if I do not perform my duties properly, I ensure my\n"
    .. "</>own death.'")
self.room:send_except(actor, tostring(self.name) .. " tells her story to " .. tostring(actor.name) .. ".")
wait(7)
self:command("sigh")
wait(0.5)
self:command("ponder")
wait(0.5)
actor:send(tostring(self.name) .. " tells you, 'But perhaps if I repent by teaching you these ancient\n"
    .. "</>magics, the goddess will release me from this place!'")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Yes, if you are willing I will teach you the power of\n"
    .. "</>druidic travel.'")
self.room:send_except(actor, tostring(self.name) .. " seems excited while telling something to " .. tostring(actor.name) .. ".")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Are you willing to learn?'")$trig$, 'da626a74ca3ed64ab7c57ad76b1f4661'),
  -- data/triggers/163/163_42_dryad_moonwell_yesno.lua
  (163, 42, $trig$local sl = string.lower(speech)

-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"yes", "no"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

if actor.name ~= globals.moon_name then
    return true
end

globals.moon_name = nil

if string.find(sl, "no") then
    self:command("frown")
    actor:send(tostring(self.name) .. " tells you, 'Very well, that is your choice.'")
    self.room:send_except(actor, tostring(self.name) .. " seems disappointed as she says something to " .. tostring(actor.name) .. ".")
    return true
end

if string.find(sl, "yes") then
    self.room:send(tostring(self.name) .. " smiles with a slight twinkle in her eye.")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Very well, I will teach you what I know.'")
    self.room:send_except(actor, tostring(self.name) .. " seems pleased as she speaks with " .. tostring(actor.name) .. ".")
    wait(2)
    actor:send(tostring(self.name) .. " tells you 'I will guide you through the proper performance of a\n"
        .. "</>complex ceremony to create a well of moonlight.'")
    wait(4)
    actor:send(tostring(self.name) .. " tells you, 'This ceremony requires several powerful symbols and\n"
        .. "</>materials.  You must attain these materials since I cannot leave this place.'")
    self.room:send_except(actor, tostring(self.name) .. " excitedly tells " .. tostring(actor.name) .. " something.")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'First we need something to mark the well's outline.'")
    self.room:send_except(actor, tostring(self.name) .. " begins telling something to " .. tostring(actor.name) .. ".")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Long ago during the Rift Wars, the goddess Mielikki was\n"
        .. "</>injured by another god, and one of the vines that surround her body was cut\n"
        .. "</>off.  As this was more than a mere plant but rather part of Her divine body, it\n"
        .. "</>survived.'")
    wait(6)
    actor:send(tostring(self.name) .. " tells you, 'I have heard tell this vine has proliferated near molten\n"
        .. "</>mountains, but is guarded by fearsome fiery beasts.'")
    wait(4)
    actor:send(tostring(self.name) .. " tells you, 'Go, recover part of this vine and bring it back safely!'")
    self.room:send_except(actor, tostring(self.name) .. " pleads with " .. tostring(actor.name) .. " desperately.")
    actor:start_quest("moonwell_spell_quest")
end$trig$, '190fc0b5da28ece27e8583ab7d8b7985'),
  -- data/triggers/163/163_50_moonwell_quest_status_checker.lua
  (163, 50, $trig$-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"status", "status?", "progress", "progress?"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

wait(0.2)

if actor:get_has_completed("moonwell_spell_quest") then
    self:say("I have already taught you to travel through moonwells.")
    return true
end

local stage = actor:get_quest_stage("moonwell_spell_quest")
local item, place

if stage == 1 or stage == 2 then
    item = {163, 50}  -- Vine of Mielikki (16350)
    place = "an island of lava and fire."
elseif stage == 3 then
    item = {480, 24}  -- The Heartstone (48024)
    place = "an ancient burial site far to the north"
elseif stage == 4 or stage == 5 then
    item = {163, 56}  -- Flask of Eleweiss (16356)
    place = "the cult of the ice dragon"
elseif stage == 6 then
    item = {52, 1}  -- Glittering ruby ring (5201)
    place = "a temple dedicated to fire"
elseif stage == 7 then
    item = {160, 6}  -- Orb of Winds (16006)
    place = "a dark fortress to the east"
elseif stage == 8 then
    self:say("Please give me your map to update.")
    return true
elseif stage == 9 then
    item = {490, 11}  -- Jade ring (49011)
    place = "a wood nymph on an island of our brothers beset by beasts"
elseif stage == 10 then
    item = {40, 3}  -- Chaos Orb (4003)
    place = "a great dragon hidden in a hellish labyrinth"
elseif stage == 11 then
    item = {550, 20}  -- Granite Ring (55020)
    place = "a large temple hidden in a mountain"
elseif stage == 12 then
    self:say("Please give me your map to make the final markings.")
    return true
else
    self:say("You haven't agreed to help me yet.")
    return true
end

local item_name = objects.template(item[1], item[2]).name
self:say("We need:")
self.room:send("</>" .. tostring(item_name) .. " from")
self.room:send("</>" .. tostring(place) .. ".")
if stage > 6 then
    self.room:send(tostring(self.name) .. " says, 'If you need a new map, say \"<b:green>I lost my map</>\".'")
end$trig$, '6a37c6ed504897696e5fddfcf864ad56'),
  -- data/triggers/163/163_51_moonwell_dryad_map_replacement.lua
  (163, 51, $trig$-- Speech phrase: i lost my map (DG num_arg 0 = the speech contains the whole phrase, on word boundaries)
local speech_padded = " " .. string.lower(speech) .. " "
if not string.find(speech_padded, "[%s%p]i lost my map[%s%p]") then
    return true  -- Not the phrase
end

wait(0.2)
local stage = actor:get_quest_stage("moonwell_spell_quest")
if stage <= 6 then
    return true
end

self:command("sigh")
self:say("It will be difficult to complete this ritual without it.")
wait(1)
self:emote("begins to draw a new map.")
wait(2)
self:emote("continues to draw...")
wait(2)
self:emote("continues to draw...")
wait(4)
self:say("There!  All set!")
wait(1)

if stage == 8 then
    self.room:spawn_object(163, 52)
elseif stage == 9 or stage == 10 then
    self.room:spawn_object(163, 53)
elseif stage == 11 then
    self.room:spawn_object(163, 54)
elseif stage == 12 then
    self.room:spawn_object(163, 55)
elseif stage == 7 then
    -- Stage 7: no map yet — dryad's redraw wouldn't have anything to mark.
    self.room:spawn_object(163, 51)
else
    self.room:spawn_object(163, 51)
end
self:command("give map " .. tostring(actor.name))$trig$, 'e2eaad4849db1c88ab7ada50aa78ffc7'),
  -- data/triggers/172/172_00_grand_master_responds_to_guild.lua
  (172, 0, $trig$-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
