        get_room(178, 72):at(function()
            self.room:spawn_mobile(178, 11)
        end)
        if world.count_mobiles(178, 12) == 0 then
            get_room(178, 72):at(function()
                self.room:spawn_mobile(178, 12)
            end)
        end
    end
end$trig$, '1f53937a82700106461075d47992e9fa'),
