                self.room:send("</>have to do is <b:cyan>[dig]</> up a handful of dirt from each place and bring it")
                self.room:send("</>back to me.'")
            end
            -- (empty room echo)
            self.room:send(tostring(self.name) .. " says, 'You can check your <b:cyan>[mace progress]</> at")
            self.room:send("</>any time.'")
        else
            self.room:send(tostring(self.name) .. " says, 'You'll need to be at least level " .. tostring(minlevel) .. " before I")
            self.room:send("</>can improve your bond with your weapon.'")
        end
    elseif actor:get_has_completed("phase_mace") then
        self:say("There is no weapon greater than the mace of disruption!")
    elseif actor:get_quest_stage("phase_mace") < macestep then
        self:say("Your mace isn't ready for improvement yet.")
    elseif actor:get_quest_stage("phase_mace") > macestep then
        self:say("I've done all I can already.")
        wait(1)
        -- switch on actor:get_quest_stage("phase_mace")
        if actor:get_quest_stage("phase_mace") == 3 then
            self.room:send(tostring(self.name) .. " says, 'The Cleric Guild is capable of some miraculous")
            self.room:send("</>crafting.  Visit the Cleric Guild Master in the Arctic Village of Ickle")
            self.room:send("</>and talk to High Priest Zalish.  He should be able to help you.'")
        elseif actor:get_quest_stage("phase_mace") == 4 then
            self.room:send(tostring(self.name) .. " says, 'Continue with the Cleric Guild Masters.  Check in")
            self.room:send("</>with the High Priestess in the City of Anduin.'")
        elseif actor:get_quest_stage("phase_mace") == 5 then
            self.room:send(tostring(self.name) .. " says, 'Sometimes to battle the dead, we need to use their")
            self.room:send("</>own dark natures against them.  Few are as knowledgeable about the dark")
            self.room:send("</>arts as Ziijhan, the Defiler, in the Cathedral of Betrayal.'")
        elseif actor:get_quest_stage("phase_mace") == 6 then
            self.room:send(tostring(self.name) .. " says, 'Return again to the Abbey of St. George and seek out")
            self.room:send("</>Silania.  Her mastry of spiritual matters will be necessary to improve")
            self.room:send("</>this mace any further.'")
        elseif actor:get_quest_stage("phase_mace") == 7 then
            self.room:send(tostring(self.name) .. " says, 'Of the few remaining who are capable of improving your")
            self.room:send("</>mace, one is a priest of a god most foul.  Find Ruin Wormheart, that")
            self.room:send("</>most heinous of Blackmourne's servators.'")
        elseif actor:get_quest_stage("phase_mace") == 8 then
            self.room:send(tostring(self.name) .. " says, 'The most powerful force in the war against the dead")
            self.room:send("</>is the sun itself.  Consult with the sun's Oracle in the ancient pyramid")
            self.room:send("</>near Anduin.'")
        elseif actor:get_quest_stage("phase_mace") == 9 then
            self.room:send(tostring(self.name) .. " says, 'With everything prepared, return to the very")
            self.room:send("</>beginning of your journey.  The High Priestess of Mielikki, the very")
            self.room:send("</>center of the Cleric Guild, will know what to do.'")
        end
    end
end$trig$, '0231a67b43452f9c56d24373c11d642f'),
  -- data/triggers/185/185_99_group_heal_status_check.lua
  (185, 99, $trig$-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"status", "status?", "progress", "progress?"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

local stage = actor:get_quest_stage("group_heal")
wait(2)

if stage == 1 then
    self.room:send(tostring(self.name) .. " says, 'Please track down the bandit raider somewhere in the")
    self.room:send("</>Gothra desert and recover our stolen medical supplies.'")
    if world.count_mobiles(185, 22) == 0 then
        get_room(11, 0):at(function() self.room:spawn_mobile(185, 22) end)
        get_room(11, 0):at(function() self.room:spawn_object(161, 6) end)
        get_room(11, 0):at(function() self.room:spawn_object(161, 6) end)
        get_room(11, 0):at(function() self:command("give scimitar bandit") end)
        get_room(11, 0):at(function() self:command("give scimitar bandit") end)
        get_room(11, 0):at(function() self.room:find_actor("bandit"):command("wear all") end)
        get_room(11, 0):at(function() self.room:find_actor("bandit"):teleport(get_room(161, 86)) end)
    end
elseif stage == 2 then
    self:say("Please find the medical supplies stolen by the bandit raider.")
elseif stage == 3 or stage == 4 then
    self.room:send(tostring(self.name) .. " says, 'You are currently trying to locate the records of a group")
    self.room:send("</>healing ritual in a lost kitchen in the Great Northern Swamp.'")
elseif stage == 5 then
    self.room:send(tostring(self.name) .. " says, 'You are visiting every <b:white>chef</> and <b:white>cook</> to get their notes on")
    self.room:send("</>the healing ritual.'")
    -- Keys match the writers (185_22 / 185_23): "group_heal:<zone>_<id>".
    local recipes = {
        { key = "group_heal:83_7",   tpl = {83, 7}    },
        { key = "group_heal:510_7",  tpl = {510, 7}   },
        { key = "group_heal:185_12", tpl = {185, 12}  },
        { key = "group_heal:300_3",  tpl = {300, 3}   },
        { key = "group_heal:502_3",  tpl = {502, 3}   },
        { key = "group_heal:103_8",  tpl = {103, 8}   },
    }
    local any = false
    for _, r in ipairs(recipes) do
        if actor:get_quest_var(r.key) then
            any = true
            break
        end
    end
    if any then
        self.room:send("</>You have already brought me notes from:")
        for _, r in ipairs(recipes) do
            if actor:get_quest_var(r.key) then
                self.room:send("- " .. tostring(mobiles.template(r.tpl[1], r.tpl[2]).name))
            end
        end
        local total = 6 - (actor:get_quest_var("group_heal:total") or 0)
        self.room:send("</>Bring me notes from " .. tostring(total) .. " more chefs.")
        self.room:send(tostring(self.name) .. " says, 'And if you need a new copy of the Rite, just say:")
        self.room:send("</><b:yellow>\"I lost the Rite\"</> and I will give you a new one.'")
    end
elseif stage == 6 then
    self.room:send(tostring(self.name) .. " says, 'You are delivering the medical packages to <b:white>injured</>, <b:white>wounded,")
    self.room:send("</><b:white>sick</>, or <b:white>hobbling</> creatures.'")
    local total = 5 - (actor:get_quest_var("group_heal:total") or 0)
    local people = {
        { key = "group_heal:185_6",  tpl = {185, 6}   },
        { key = "group_heal:464_14", tpl = {464, 14}  },
        { key = "group_heal:430_20", tpl = {430, 20}  },
        { key = "group_heal:125_13", tpl = {125, 13}  },
        { key = "group_heal:361_3",  tpl = {361, 3}   },
        { key = "group_heal:588_3",  tpl = {588, 3}   },
        { key = "group_heal:300_54", tpl = {300, 54}  },
    }
    local any = false
    for _, p in ipairs(people) do
        if actor:get_quest_var(p.key) then
            any = true
            break
        end
    end
    if any then
        self.room:send("You have aided:")
        for _, p in ipairs(people) do
            if actor:get_quest_var(p.key) then
                self.room:send("- " .. tostring(mobiles.template(p.tpl[1], p.tpl[2]).name))
            end
        end
    end
    if total == 1 then
        self.room:send("You need to deliver " .. tostring(total) .. " more packet.")
    else
        self.room:send("You need to deliver " .. tostring(total) .. " more packets.")
    end
else
    if actor:get_has_completed("group_heal") then
        self:say("You finished the quest to learn Group Heal already.")
    else
        self:say("You aren't working on a quest with me.")
    end
end$trig$, 'f1bcc51956b75330d2c9d454c18c3c32'),
