  -- data/triggers/238/238_16_mage_speak3.lua
  (238, 16, $trig$-- cleric warrior rogue mercenary bugs bug dragons dragon orcs orc demons demon undead

local speech_lower = string.lower(speech)

-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"barbarian", "human", "half-elf", "half-elven", "halfling", "gnome", "sorcerer", "cleric", "warrior", "rogue", "mercenary", "bugs", "bug", "dragons", "dragon", "orcs", "orc", "demons", "demon", "undead"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end
if not globals.question then
    return true  -- No question pending
end
local question = globals.question
local correct = nil
if question == 1 then
    if speech_lower == "barbarian" then
        correct = "yes"
    elseif speech_lower == "human" or speech_lower == "half-elf" or speech_lower == "halfling" or speech_lower == "gnome" or speech_lower == "half-elven" then
        correct = "no"
    end
elseif question == 2 then
    if speech_lower == "human" then
        correct = "yes"
    elseif speech_lower == "barbarian" or speech_lower == "half-elf" or speech_lower == "halfling" or speech_lower == "gnome" or speech_lower == "half-elven" then
        correct = "no"
    end
elseif question == 3 then
    if speech_lower == "rogue" then
        correct = "yes"
    elseif speech_lower == "sorcerer" or speech_lower == "cleric" or speech_lower == "warrior" or speech_lower == "mercenary" then
        correct = "no"
    end
elseif question == 4 then
    if speech_lower == "orcs" or speech_lower == "orc" then
        correct = "yes"
    elseif speech_lower == "bugs" or speech_lower == "dragons" or speech_lower == "demons" or speech_lower == "undead" or speech_lower == "bug" or speech_lower == "dragon" or speech_lower == "demon" then
        correct = "no"
    end
else
    self:command("wince")
    self:say("Something is terribly wrong...please inform a god.")
    return true
end

if correct == "no" then
    globals.question = nil
    -- Respawn the Tempest and re-arm its quest state
    if world.count_mobiles(238, 3) == 0 then
        get_room(238, 90):at(function()
            self.room:spawn_mobile(238, 3)
        end)
    end
    if world.count_mobiles(238, 3) > 0 then
        get_room(238, 90):at(function()
            run_room_trigger(238, 13)
        end)
    end
    self:emote("swears profusely as the ice reforms over the symbols on the wall.")
    wait(1)
    actor:send(tostring(self.name) .. " casts a dirty look at you.")
    self.room:send_except(actor, tostring(self.name) .. " scowls angrily at " .. tostring(actor.name) .. ".")
    self:say("That was wrong!")
    wait(2)
    self:command("sigh")
    self:say("Now the Tempest is back...  We would need to banish him again for another chance.")
elseif correct == "yes" then
    globals.question = nil
    wait(1)
    self:emote("nods slowly and traces one of the signs.")
    wait(1)
    self:emote("smiles happily.")
    self:say("Excellent!  That is indeed the correct answer!")
    wait(1)
    self:command("thank " .. tostring(actor.name))
    self:say("You have helped me more than I can say.  How can I ever repay you?")
    wait(2)
    self:emote("gets a big grin on his face.")
    self.room:spawn_object(238, 16)
    self:command("give glowing-key " .. tostring(actor.name))
    self:command("drop glowing-key")
    self:command("bow " .. tostring(actor.name))
    wait(1)
    self:say("Use it wisely!")
end$trig$, '9f301bf2c26bd65325509189271888a1'),
  -- data/triggers/238/238_18_tempest_fight_room.lua
  (238, 18, $trig$-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"secretcommandtohurtpeople"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

local howmany = math.floor(self.room.actor_count / 2)
local hits = 0
local iterations = 0
while hits < howmany do
    iterations = iterations + 1
    -- Bail out if we somehow can't find enough valid targets
    if iterations > 15 then
        break
    end
    local actors = self.room.actors
    if #actors == 0 then
        break
    end
    local victim = actors[random(1, #actors)]
    if not (victim.zone_id == 238 and victim.local_id == 3) then
        local damage = 150 + random(1, 30)
        if victim:has_effect(Effect.Sanctuary) then
            damage = damage - 75
        elseif victim:has_effect(Effect.Stone) then
            damage = damage - 75
        end
        local globed = victim:has_effect(Effect.Major_Globe)
        if globed then
            damage = math.floor(damage / 2)
        end
        local damage_dealt = victim:damage(damage)  -- type: shock
        if damage_dealt == 0 then
            victim:send("<b:blue>The lightning arcs off the Tempest Manifest, but is repelled from you!</>")
            self.room:send_except(victim, "<b:blue>Lightning arcs off the Tempest Manifest, but is repelled from " .. tostring(victim.name) .. "!</>")
        elseif globed then
            victim:send("<b:red>The <blue>lightning <red>rips through the shimmering globe around your body and right into you!</> (<b:red>" .. tostring(damage_dealt) .. "</>)")
            self.room:send_except(victim, "<b:red>The shimmering globe around " .. tostring(victim.name) .. "'s body wavers as the <blue>lightning <red>rips through it.</> (<yellow>" .. tostring(damage_dealt) .. "</>)")
        else
            victim:send("<b:blue>The lightning arcs off the Tempest Manifest and into your body, causing your muscles to spasm wildly!</> (<b:red>" .. tostring(damage_dealt) .. "</>)")
            self.room:send_except(victim, "<b:blue>Lightning arcs off the Tempest Manifest, jolting " .. tostring(victim.name) .. " with massive force!</> (<yellow>" .. tostring(damage_dealt) .. "</>)")
        end
        hits = hits + 1
    end
end$trig$, '9bd9618eadf8fd5a74c7cac6d9f979aa'),
