    place = "a druid past the Vale of Anlun"
elseif stage == 3 then
    next_item = "the Crystal Telescope"
    place = "an observer of the cold village"
elseif stage == 4 then
    next_item = "a glass globe"
    place = "the Valley of the Frost Elves"
elseif stage == 5 then
