end
local stage = actor:get_quest_stage("hell_gate")
wait(0.2)
-- switch on stage
do
    local _sw1 = string.lower(tostring(stage or ""))
    if tonumber(_sw1) == 1 then
        self.room:send(tostring(self.name) .. " says, 'We are preparing to open a door to")
