    elseif tonumber(_sw1) == 4 then
        self:say("Give the spider-shaped dagger back to me.")
    elseif tonumber(_sw1) == 5 then
        self:say("Slay Larathiel and release our demon lord!")
    else
        if actor:get_has_completed("hell_gate") then
            self:say("You have already learned to open the gates of Hell.")
        else
            self:say("You're not working with me.")
        end
    end
end$trig$, '23e1405c5e9a34ea2d2e1727f9a28977'),
  -- data/triggers/564/564_11_hell_gate_dagger_replacement.lua
  (564, 11, $trig$-- matches over single words like "I" or "a" would over-fire).

-- Speech phrase: i need a new dagger (DG num_arg 0 = the speech contains the whole phrase, on word boundaries)
local speech_padded = " " .. string.lower(speech) .. " "
if not string.find(speech_padded, "[%s%p]i need a new dagger[%s%p]") then
    return true  -- Not the phrase
end

