            self:say("I already taught you Creeping Doom!")
        else
            self:say("You haven't started to dream my Dream yet.")
        end
        return true
    end
end

local function key(it) return it.z .. "_" .. it.l end
local function name(it) return objects.template(it.z, it.l).name end

self.room:send("You are trying to " .. tostring(step) .. ".")
local have1 = actor:get_quest_var("creeping_doom:" .. key(item1))
local have2 = actor:get_quest_var("creeping_doom:" .. key(item2))
local have3 = actor:get_quest_var("creeping_doom:" .. key(item3))
